package backend

type Item struct {
	ID   string
	Name string
}

type Response struct {
	Items     []Item
	NextCursor *string
}

var items = []Item{
	{ID: "i1", Name: "one"},
	{ID: "i2", Name: "two"},
	{ID: "i3", Name: "three"},
}

func cursorValue(value string) *string {
	return &value
}

// FetchItems returns one page. A nil cursor is the initial request; a non-nil
// cursor is passed through unchanged as the subsequent request cursor.
func FetchItems(cursor *string, limit int) Response {
	if limit < 1 {
		return Response{Items: []Item{}, NextCursor: nil}
	}

	start := 0
	if cursor != nil {
		switch *cursor {
		case "cursor-2":
			start = 2
		default:
			return Response{Items: []Item{}, NextCursor: nil}
		}
	}

	end := start + limit
	if end > len(items) {
		end = len(items)
	}

	page := append([]Item(nil), items[start:end]...)
	var next *string
	if end < len(items) {
		next = cursorValue("cursor-2")
	}
	return Response{Items: page, NextCursor: next}
}

// FetchAll requests the next page with exactly the cursor returned by the
// preceding response and stops once next_cursor is null.
func FetchAll(limit int) []Item {
	var cursor *string
	all := []Item{}
	for {
		response := FetchItems(cursor, limit)
		all = append(all, response.Items...)
		if response.NextCursor == nil {
			return all
		}
		cursor = response.NextCursor
	}
}

